package com.priyamart.controller;
import com.priyamart.model.*; import com.priyamart.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*;
@Controller public class ShopController {
 private final ProductRepository products; private final OrderRepository orders;
 public ShopController(ProductRepository p,OrderRepository o){products=p;orders=o;}
 private User u(HttpSession s){return (User)s.getAttribute("user");}
 @GetMapping({"/","/products"}) public String home(@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String category,HttpSession s,Model m){User x=u(s);if(x==null)return"redirect:/login";if("ADMIN".equals(x.getRole()))return"redirect:/admin";m.addAttribute("products",products.search(q,category));m.addAttribute("categories",products.categories());m.addAttribute("q",q);m.addAttribute("selectedCategory",category);m.addAttribute("user",x);return"index";}
 @GetMapping("/dashboard") public String dashboard(HttpSession s,Model m){User x=u(s);if(x==null)return"redirect:/login";if("ADMIN".equals(x.getRole()))return"redirect:/admin";m.addAttribute("user",x);m.addAttribute("orders",orders.byUser(x.getId()));return"dashboard";}
 @GetMapping("/account") public String account(HttpSession s,Model m){User x=u(s);if(x==null)return"redirect:/login";m.addAttribute("user",x);m.addAttribute("orders",orders.byUser(x.getId()));return"account";}
 @GetMapping("/product/{id}") public String product(@PathVariable int id,HttpSession s,Model m){if(u(s)==null)return"redirect:/login";m.addAttribute("product",products.one(id));return"product";}
 @PostMapping("/cart/add") public String add(@RequestParam int id,@RequestParam(defaultValue="1") int q,HttpSession s){if(u(s)==null)return"redirect:/login";Product p=products.one(id);int qty=Math.max(1,Math.min(q,p.getStock()));if(qty==0)return"redirect:/products";List<CartItem> c=cart(s);for(CartItem i:c)if(i.getProduct().getId()==id){i.setQuantity(Math.min(i.getQuantity()+qty,p.getStock()));return"redirect:/cart";}c.add(new CartItem(p,qty));return"redirect:/cart";}
 @PostMapping("/cart/update") public String update(@RequestParam int id,@RequestParam int q,HttpSession s){for(CartItem i:cart(s))if(i.getProduct().getId()==id)i.setQuantity(Math.max(1,Math.min(q,i.getProduct().getStock())));return"redirect:/cart";}
 @GetMapping("/cart") public String cartPage(HttpSession s,Model m){if(u(s)==null)return"redirect:/login";List<CartItem> c=cart(s);m.addAttribute("cart",c);m.addAttribute("total",c.stream().mapToDouble(CartItem::getTotal).sum());return"cart";}
 @PostMapping("/cart/remove") public String remove(@RequestParam int id,HttpSession s){cart(s).removeIf(i->i.getProduct().getId()==id);return"redirect:/cart";}
 @PostMapping("/checkout") public String checkout(@RequestParam String address,HttpSession s,Model m){User x=u(s);List<CartItem> c=cart(s);if(x==null)return"redirect:/login";if(c.isEmpty())return"redirect:/cart";int id=orders.create(x,c,address);double total=c.stream().mapToDouble(CartItem::getTotal).sum();c.clear();m.addAttribute("orderId",id);m.addAttribute("total",total);return"success";}
 @GetMapping("/admin") public String admin(HttpSession s,Model m){User x=u(s);if(x==null||!"ADMIN".equals(x.getRole()))return"redirect:/login";m.addAttribute("products",products.all());m.addAttribute("productCount",products.count());m.addAttribute("lowStock",products.lowStock());m.addAttribute("orderCount",orders.count());m.addAttribute("revenue",orders.revenue());return"admin";}
 @PostMapping("/admin/add") public String addProduct(Product p,HttpSession s){User x=u(s);if(x==null||!"ADMIN".equals(x.getRole()))return"redirect:/login";products.add(p);return"redirect:/admin";}
 @PostMapping("/admin/delete") public String delete(@RequestParam int id,HttpSession s){User x=u(s);if(x==null||!"ADMIN".equals(x.getRole()))return"redirect:/login";products.delete(id);return"redirect:/admin";}
 @SuppressWarnings("unchecked") private List<CartItem> cart(HttpSession s){List<CartItem> c=(List<CartItem>)s.getAttribute("cart");if(c==null){c=new ArrayList<>();s.setAttribute("cart",c);}return c;}
}
